import React, { useState } from 'react';

function DestinationGrid() {
  const [currentTicketIdx, setCurrentTicketIdx] = useState(0);
  const [fade, setFade] = useState(true);

  const ticketList = [
    {
      id: 1,
      title: "아비정전 4K 리마스터링",
      subtitle: "메가박스가 제안하는 <아비정전 4K 리마스터링>을 가장 잘 간직하는 방법",
      ticketNumber: "No. 43",
      image: "/img/event/03.png" 
    },
    {
      id: 2,
      title: "싱어게인",
      subtitle: "메가박스가 제안하는 <싱어게인>을 가장 잘 간직하는 방법",
      ticketNumber: "No. 105",
      image: "/img/event/02.jpg"
    },
    {
      id: 3,
      title: "인 더 그레이",
      subtitle: "메가박스가 제안하는 <인 더 그레이>를 가장 잘 간직하는 방법",
      ticketNumber: "No. 184",
      image: "/img/event/01.jpg"
    }
  ];

  const changeSlide = (newIndex) => {
    setFade(false);
    setTimeout(() => {
      setCurrentTicketIdx(newIndex);
      setFade(true);
    }, 200);
  };

  const handlePrev = () => {
    const nextIdx = currentTicketIdx === 0 ? ticketList.length - 1 : currentTicketIdx - 1;
    changeSlide(nextIdx);
  };

  const handleNext = () => {
    const nextIdx = currentTicketIdx === ticketList.length - 1 ? 0 : currentTicketIdx + 1;
    changeSlide(nextIdx);
  };

  const currentTicket = ticketList[currentTicketIdx];

  return (
    <section className="w-full bg-gradient-to-br from-[#120f1d] via-[#1a1229] to-[#0f0b1a] pt-6 pb-0 flex flex-col justify-between relative overflow-hidden text-white animate-fade-in">
      
      {/* 배경 감성 그라데이션 광채 효과 */}
      <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[400px] h-[400px] bg-purple-600/10 rounded-full blur-3xl pointer-events-none" />

      {/* 상단 '혜택' 타이틀 영역 */}
      <div className="w-full max-w-5xl px-6 mx-auto z-10">
        <div className="flex justify-between items-center mb-3 pb-2 border-b border-purple-500/20">
          <h2 className="text-lg font-black text-purple-300 tracking-tight">혜택</h2>
          <button className="text-lg text-purple-300 font-bold hover:text-white transition">+</button>
        </div>

        {/* 오리지널 티켓 흰색 카드 박스 영역 */}
        <div className="bg-white rounded-2xl p-6 md:p-8 shadow-[0_15px_35px_rgba(0,0,0,0.5)] border border-zinc-100 flex flex-col md:flex-row items-center justify-between gap-6 text-zinc-900">
          
          {/* [좌측] 설명 텍스트 영역 */}
          <div className={`max-w-md space-y-2.5 z-10 transition-opacity duration-300 ${fade ? 'opacity-100' : 'opacity-0'}`}>
            <span className="text-[11px] font-bold text-zinc-500 block tracking-widest uppercase">메가박스 오리지널 티켓</span>
            <h3 className="text-3xl md:text-4xl font-black text-zinc-900 tracking-tight leading-none drop-shadow-sm">
              ORIGINAL TICKET
            </h3>
            
            <p className="text-xs text-zinc-700 font-medium leading-relaxed tracking-tight">
              {currentTicket.subtitle}
            </p>

            {/* 인디케이터 및 컨트롤러 */}
            <div className="flex items-center gap-4 pt-2">
              <div className="w-28 h-1 bg-zinc-200 relative rounded-full overflow-hidden">
                <div 
                  className="h-full bg-[#503396] transition-all duration-300 shadow-[0_0_10px_rgba(80,51,150,0.4)]"
                  style={{ width: `${((currentTicketIdx + 1) / ticketList.length) * 100}%` }}
                />
              </div>
              <div className="flex items-center gap-2 text-xs font-black text-zinc-700">
                <button onClick={handlePrev} className="hover:text-[#503396] px-0.5 text-zinc-500">&lt;</button>
                <button onClick={handleNext} className="hover:text-[#503396] px-0.5 text-zinc-500">&gt;</button>
                <span className="text-zinc-300 font-normal">||</span>
                <span className="font-bold text-zinc-900">{currentTicketIdx + 1} / {ticketList.length}</span>
              </div>
            </div>
          </div>

          {/* [우측] 💡 그림자를 완전히 제거하고 흰색 카드 배경(bg-white)과 경계 없이 완전히 밀착되도록 수정 */}
          <div className={`relative flex items-center justify-center transition-opacity duration-300 ${fade ? 'opacity-100' : 'opacity-0'}`}>
            <div 
              className="relative flex flex-col items-center justify-center bg-white"
              style={{ width: '280px', height: '220px' }}
            >
              {currentTicket.image ? (
                <img 
                  src={currentTicket.image} 
                  alt={currentTicket.title} 
                  className="w-full h-full object-contain bg-white transition-transform duration-500 hover:scale-105" 
                />
              ) : (
                <div className="text-center p-4">
                  <span className="text-xs font-bold text-zinc-400 block mb-1">이미지 공간</span>
                </div>
              )}
            </div>
          </div>

        </div>
      </div>

      {/* 2. 중간 이벤트 카드 배너 */}
      <div className="w-full max-w-5xl px-6 mx-auto mt-4 z-20 grid grid-cols-1 md:grid-cols-2 gap-4">
        
        {/* 배너 1 */}
        <div className="bg-[#161022]/90 backdrop-blur-sm text-white rounded-2xl p-4 shadow-xl border border-purple-500/20 flex items-center justify-between">
          <div>
            <div className="flex items-center gap-2 mb-1">
              <span className="text-[9px] font-extrabold text-sky-400 bg-sky-950/80 px-2 py-0.5 rounded-full border border-sky-800/50">toss payments</span>
              <span className="text-[9px] text-purple-400">×</span>
              <span className="text-[9px] font-extrabold text-purple-200">MEGABOX</span>
            </div>
            <h4 className="text-sm font-black leading-snug tracking-tight text-white">
              퀵계좌이체 결제 시 <strong className="text-sky-400">0.3% 즉시할인</strong>
            </h4>
          </div>
          <div className="text-3xl">🍿</div>
        </div>

        {/* 배너 2 */}
        <div className="bg-[#161022]/90 backdrop-blur-sm text-white rounded-2xl p-4 shadow-xl border border-purple-500/20 flex items-center justify-between">
          <div>
            <span className="text-[9px] font-bold text-purple-300 block mb-1">토스 퀵계좌이체</span>
            <h4 className="text-sm font-black text-white tracking-tight">
              0.3% 즉시할인
            </h4>
          </div>
          <div className="w-10 h-10 rounded-full bg-purple-600/20 border border-purple-500/30 flex items-center justify-center text-purple-300 font-black text-sm shadow-inner">
            %
          </div>
        </div>

      </div>

      {/* 3. 하단 보라색 퀵 메뉴 바 */}
      <div className="w-full bg-[#422678] py-14 px-6 text-white flex justify-center shadow-inner mt-6 z-10 border-t border-purple-500/20">
        <div className="w-full max-w-4xl flex items-center justify-around text-center">
          
          <div className="flex flex-col items-center gap-3 cursor-pointer group">
            <svg className="w-8 h-8 stroke-current text-purple-200 group-hover:text-white transition-colors" fill="none" viewBox="0 0 24 24" strokeWidth="1.6">
              <path strokeLinecap="round" strokeLinejoin="round" d="M12 2l9 4.909v9.182L12 21l-9-4.909V6.909L12 2z" />
            </svg>
            <span className="text-sm font-extrabold tracking-wider text-purple-100 group-hover:text-white">VIP LOUNGE</span>
          </div>

          <div className="flex flex-col items-center gap-3 cursor-pointer group">
            <svg className="w-8 h-8 stroke-current text-purple-200 group-hover:text-white transition-colors" fill="none" viewBox="0 0 24 24" strokeWidth="1.6">
              <circle cx="12" cy="7" r="4" />
              <path strokeLinecap="round" strokeLinejoin="round" d="M4 21v-2a4 4 0 0 1 4-4h8a4 4 0 0 1 4 4v2" />
            </svg>
            <span className="text-sm font-extrabold tracking-wider text-purple-100 group-hover:text-white">멤버십</span>
          </div>

          <div className="flex flex-col items-center gap-3 cursor-pointer group">
            <svg className="w-8 h-8 stroke-current text-purple-200 group-hover:text-white transition-colors" fill="none" viewBox="0 0 24 24" strokeWidth="1.6">
              <rect x="2" y="5" width="20" height="14" rx="2" />
              <path strokeLinecap="round" strokeLinejoin="round" d="M2 10h20" />
            </svg>
            <span className="text-sm font-extrabold tracking-wider text-purple-100 group-hover:text-white">할인카드안내</span>
          </div>

          <div className="flex flex-col items-center gap-3 cursor-pointer group">
            <svg className="w-8 h-8 stroke-current text-purple-200 group-hover:text-white transition-colors" fill="none" viewBox="0 0 24 24" strokeWidth="1.6">
              <path strokeLinecap="round" strokeLinejoin="round" d="M20 12v10H4V12M2 7h20v5H2zM12 22V7M12 7H7.5a2.5 2.5 0 0 1 0-5C11 2 12 7 12 7zM12 7h4.5a2.5 2.5 0 0 0 0-5C13 2 12 7 12 7z" />
            </svg>
            <span className="text-sm font-extrabold tracking-wider text-purple-100 group-hover:text-white">이벤트</span>
          </div>

          <div className="flex flex-col items-center gap-3 cursor-pointer group">
            <svg className="w-8 h-8 stroke-current text-purple-200 group-hover:text-white transition-colors" fill="none" viewBox="0 0 24 24" strokeWidth="1.6">
              <path strokeLinecap="round" strokeLinejoin="round" d="M7 21h10a2 2 0 0 0 2-2V9.414a1 1 0 0 0-.293-.707l-5.414-5.414A1 1 0 0 0 12.586 3H7a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2z" />
            </svg>
            <span className="text-sm font-extrabold tracking-wider text-purple-100 group-hover:text-white">스토어</span>
          </div>

        </div>
      </div>

    </section>
  );
}

export default DestinationGrid;
